#include <stdio.h>

int main(void) {
    char operation = '+';
    int a = 8, b = 2;
    switch (operation) {
        case '+': printf("%d\n", a + b); break;
        case '-': printf("%d\n", a - b); break;
        default: puts("Unsupported operation"); break;
    }
    return 0;
}
